import{_ as t,o as a,c as s,ah as i}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse(`{"title":"Registrar's Office","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/secretariat/index.md","filePath":"src/en/guide/secretariat/index.md"}`),r={name:"en/guide/secretariat/index.md"};function n(o,e,d,c,h,l){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="registrar-s-office" tabindex="-1">Registrar&#39;s Office <a class="header-anchor" href="#registrar-s-office" aria-label="Permalink to &quot;Registrar&#39;s Office&quot;">​</a></h1><p>The registrar&#39;s office is the entry point for applications: you review the applications submitted by families — online through the public form, or entered directly by the cashier for a family visiting in person — and decide whether to approve or reject them. You also handle requests to transfer an already-enrolled student from one site to another, and class changes within a site. The <strong>Students &amp; admissions</strong> space gives you access to three pages:</p><ul><li><strong><a href="/era-guide/en/guide/secretariat/candidatures.html">Applications to review</a></strong> — the queue of applications received, with their attached documents and the decision to assign a student to a class.</li><li><strong><a href="/era-guide/en/guide/secretariat/transferts-sites.html">Inter-site transfers</a></strong> — requests to transfer a student between two of the school&#39;s sites.</li><li><strong><a href="/era-guide/en/guide/secretariat/changements-de-classe.html">Class changes</a></strong> — moving a student to another class on the same site, for instance after a change of orientation.</li></ul><p>In a higher education institution, the <strong>Higher education</strong> space adds <strong><a href="/era-guide/en/guide/secretariat/releves-attestations.html">Transcripts and certificates</a></strong>: published transcripts and certificates of completion, to print.</p><p>Once an application is approved, the student is enrolled in a class and their financial record appears with the cashier, who takes over from there for fees and payments — see the <a href="/era-guide/en/guide/caissier/">cashier guide</a>.</p><h2 id="papers-in-students-files" tabindex="-1">Papers in students&#39; files <a class="header-anchor" href="#papers-in-students-files" aria-label="Permalink to &quot;Papers in students&#39; files&quot;">​</a></h2><p>If the school has activated document management, the <strong>Documents</strong> space lets you, by default, file and validate students&#39; papers (enrollment file, birth certificate…), for example when a family brings them to the desk. See <a href="/era-guide/en/guide/gestion-documentaire/">Document management</a>.</p>',7)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
